init_esm_shims();
import { createHash as createHash7 } from "crypto";
import { readFile as readFile18 } from "fs/promises";
import { join as join36 } from "path";
async function hashSourceFiles(projectRoot, sourceFiles) {
  const hash = createHash7("sha1");
  for (const relativePath of [...new Set(sourceFiles)].sort()) {
    hash.update(`path:${relativePath}\0`);
    try {
      hash.update(await readFile18(join36(projectRoot, relativePath), "utf8"));
    } catch {
      hash.update(`missing\0`);
    }
  }
  return `sha1:${hash.digest("hex").slice(0, 7)}`;
}

